style.css:
@-moz-document domain("spotify.com") {
/* 1. Fondo conectado con la sección de imagen */
    .Root__main-view, 
    .main-view-container,
    [data-testid="playlist-page"],
    .desktop-mainView-mainViewContent {
        background-image: url("/*[[fondoOmar]]*/") !important;
        background-size: cover !important;
        background-position: center !important;
        background-repeat: no-repeat !important;
        background-attachment: fixed !important;
    }

    /* Capa oscura para legibilidad */
    .Root__main-view::before {
        content: "";
        position: absolute;
        top: 0; left: 0; right: 0; bottom: 0;
        background: rgba(7, 10, 29, 0.4) !important;
        pointer-events: none;
        z-index: 0;
    }

    /* 2. Detalles conectados con tu sección de color */
    :root {
        --spice-text: /*[[neonColor]]*/ !important;
        --spice-button: /*[[neonColor]]*/ !important;
        --spice-notification: /*[[neonColor]]*/ !important;
    }

    .main-playButton-PlayButton,
    button[data-testid="play-button"],
    .control-button--active,
    .main-navigationLink-active {
        background-color: /*[[neonColor]]*/ !important;
        color: #000000 !important;
    }

    a:hover, 
    .main-trackList-trackListRow:hover .main-trackList-rowTitle {
        color: /*[[neonColor]]*/ !important;
    }

    .playback-bar .x-progressBar-fill {
        background-color: /*[[neonColor]]*/ !important;
    }
}
